<script>
document.addEventListener('DOMContentLoaded',()=>{
 const type=document.getElementById('depositType');if(!type)return;
 const method=document.getElementById('depositMethod'),proof=document.getElementById('depositProof');
 const update=()=>{const deduction=type.value==='deduction';method.disabled=deduction;method.required=!deduction;proof.disabled=deduction;proof.required=!deduction&&['Bank Transfer','GCash','Maya'].includes(method.value);};
 type.addEventListener('change',update);method.addEventListener('change',update);update();
});
</script>
